"use client";

import { ExampleAudit, type ExampleAuditData } from "./ExampleAudit";
import { ExampleComparables, type ComparablesBlock } from "./ExampleComparables";
import data from "./example-audit.json";
import comparables from "./example-comparables.json";

// example-audit.json is byte-for-byte from the WriteUp-example-audit-pack
// handover folder (Kestrel House lender example, 28 Oct 2026) and is
// generated by the WriteUp app: don't edit it here. ExampleAudit.tsx is the
// pack's copy plus one website addition, the `afterChecklist` slot: if a new
// pack is dropped in, add that slot back (or the comparables panel vanishes).
// The comparables panel (ExampleComparables.tsx, data in
// example-comparables.json) is website-only for now: the app's lender demo
// has no comparables yet. Harry asked for it, 6 Nov 2026.
// Mounted with `data` only: the schedule panel opens at the top with Unit A
// expanded, the amber "Hypothetical example audit" notice shows above
// everything, and the Red Book checklist starts closed.
// `.app-render` (globals.css) makes the site draw the component's classes the
// way the app does.
export function ExampleAuditView() {
  return (
    <div className="app-render">
      <ExampleAudit
        data={data as ExampleAuditData}
        afterChecklist={<ExampleComparables block={comparables as ComparablesBlock} />}
      />
    </div>
  );
}
